async function retry(fn, attempts) {
  try {
    return await fn();
  } catch (err) {
    if (attempts <= 1) throw err;
    return retry(fn, attempts - 1);
  }
}
let count = 0;
retry(async () => {
  count++;
  if (count < 3) throw new Error('fail');
  return 'success';
}, 3).then(r => console.log(r));
